const input = $input.item.json || {};

const rawQuery = input.query ?? input.q ?? input.searchQuery;
if (typeof rawQuery !== 'string' || !rawQuery.trim()) {
  throw new Error('Missing required input field: query');
}

const parseInteger = (value, fallback) => {
  const parsed = parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const normalizeString = (value, fallback) => {
  if (typeof value !== 'string') return fallback;
  const trimmed = value.trim();
  return trimmed || fallback;
};

const safesearchAllowed = new Set(['off', 'moderate', 'strict']);
const freshnessAllowed = new Set(['', 'pd', 'pw', 'pm', 'py']);

const count = clamp(parseInteger(input.count ?? input.limit, 10), 1, 20);
const maxContentChars = clamp(parseInteger(input.maxContentChars ?? input.max_content_chars, 6000), 1000, 200000);
const requestTimeoutMs = clamp(parseInteger(input.requestTimeoutMs ?? input.request_timeout_ms, 60000), 1000, 300000);
const rateLimitMaxRequests = clamp(parseInteger(input.rateLimitMaxRequests ?? input.rate_limit_max_requests, 20), 1, 1000);
const rateLimitWindowSeconds = clamp(parseInteger(input.rateLimitWindowSeconds ?? input.rate_limit_window_seconds, 60), 1, 3600);
const rateLimitSleepBufferSeconds = clamp(parseInteger(input.rateLimitSleepBufferSeconds ?? input.rate_limit_sleep_buffer_seconds, 5), 0, 3600);
const maxAttempts = clamp(parseInteger(
  input.maxAttempts ?? input.max_attempts ?? input.retryMaxAttempts ?? input.retry_max_attempts ?? input.retryCount ?? input.retry_count ?? input.retries,
  3
), 1, 20);

const safesearchInput = normalizeString(input.safesearch, 'moderate');
const freshnessInput = normalizeString(input.freshness, '');

const request = {
  query: rawQuery.trim(),
  count,
  maxContentChars,
  requestTimeoutMs,
  redisRateLimitKey: normalizeString(input.redisRateLimitKey ?? input.redis_rate_limit_key, 'jina_reader:free:rpm'),
  rateLimitMaxRequests,
  rateLimitWindowSeconds,
  rateLimitSleepBufferSeconds,
  maxAttempts,
  country: normalizeString(input.country, 'US').toUpperCase(),
  search_lang: normalizeString(input.search_lang ?? input.searchLang, 'en'),
  ui_lang: normalizeString(input.ui_lang ?? input.uiLang, 'en-US'),
  safesearch: safesearchAllowed.has(safesearchInput) ? safesearchInput : 'moderate',
  freshness: freshnessAllowed.has(freshnessInput) || /^\d{4}-\d{2}-\d{2}to\d{4}-\d{2}-\d{2}$/.test(freshnessInput)
    ? freshnessInput
    : '',
  requestedAt: new Date().toISOString()
};

return { json: request };

const brave = $input.item.json || {};
const request = $('Normalize Input').first().json;
const webResults = Array.isArray(brave.web?.results) ? brave.web.results : [];

const normalizeUrlKey = (url) => String(url || '').trim().replace(/\/$/, '');
const seenUrls = new Set();
const candidates = [];

for (const result of webResults) {
  const url = String(result.url || '').trim();
  if (!url) continue;

  const key = normalizeUrlKey(url);
  if (seenUrls.has(key)) continue;
  seenUrls.add(key);

  candidates.push({
    rank: candidates.length + 1,
    title: result.title || '',
    url,
    description: result.description || '',
    age: result.age || null,
    pageAge: result.page_age || null,
    language: result.language || null,
    familyFriendly: typeof result.family_friendly === 'boolean' ? result.family_friendly : null,
    extraSnippets: Array.isArray(result.extra_snippets) ? result.extra_snippets : [],
    profile: result.profile
      ? {
          name: result.profile.name || null,
          url: result.profile.url || null,
          longName: result.profile.long_name || null,
          img: result.profile.img || null,
        }
      : null,
    source: 'brave:web'
  });

  if (candidates.length >= request.count) break;
}

const requestWithCounts = {
  ...request,
  candidateCount: candidates.length,
  readCount: candidates.length,
  readerWorkflow: 'Jina Reader - Fetch URL'
};

if (candidates.length === 0) {
  return {
    json: {
      emptyResult: true,
      request: requestWithCounts,
      candidateCount: 0,
      record: null,
      readerWorkflowInput: null
    }
  };
}

return candidates.map((record) => ({
  json: {
    request: requestWithCounts,
    candidateCount: candidates.length,
    record,
    readerWorkflowInput: {
      url: record.url,
      maxContentChars: request.maxContentChars,
      requestTimeoutMs: request.requestTimeoutMs,
      redisRateLimitKey: request.redisRateLimitKey,
      rateLimitMaxRequests: request.rateLimitMaxRequests,
      rateLimitWindowSeconds: request.rateLimitWindowSeconds,
      rateLimitSleepBufferSeconds: request.rateLimitSleepBufferSeconds,
      maxAttempts: request.maxAttempts
    }
  }
}));

const readerResponses = $input.all().map((item) => item.json || {});
const queueItems = $('Build Reader Queue').all().map((item) => item.json || {});

const byUrl = new Map();
for (const item of queueItems) {
  const url = item.record?.url || item.readerWorkflowInput?.url;
  if (url && !byUrl.has(url)) byUrl.set(url, item);
}

const getStatus = (response) => {
  if (response.status === 'ok') return 'ok';
  if (response.status === 'error') return 'error';
  return response.fetched ? 'ok' : 'error';
};

return readerResponses.map((response, index) => {
  const url = response.url || response.request?.url || response.reader?.url || null;
  const source = byUrl.get(url) || queueItems[index] || {};
  const record = source.record || { rank: index + 1, url };
  const status = getStatus(response);
  const content = typeof response.content === 'string' ? response.content : null;

  return {
    json: {
      request: source.request || {},
      candidateCount: source.candidateCount ?? queueItems.length,
      record: {
        ...record,
        readerRank: record.rank || index + 1,
        content,
        reader: {
          status,
          fetched: Boolean(response.fetched),
          provider: 'jina_reader',
          readerUrl: response.readerUrl || response.reader?.readerUrl || null,
          contentType: response.contentType || (content ? 'markdown' : null),
          contentChars: response.contentChars || (content ? content.length : 0),
          originalContentChars: response.originalContentChars || 0,
          truncated: Boolean(response.truncated),
          content,
          error: response.error || null,
          retry: response.retry || null,
          rateLimit: response.rateLimit || null,
          standaloneStatus: response.status || null,
          receivedAt: response.receivedAt || null
        }
      },
      processedAt: new Date().toISOString()
    }
  };
});

const items = $input.all().map((item) => item.json || {});
const first = items[0] || {};
const request = first.request || {};

const records = items
  .filter((item) => item.record && !item.emptyResult)
  .map((item) => item.record)
  .sort((a, b) => (a.rank || 0) - (b.rank || 0));

const readerStats = records.reduce((stats, record) => {
  const status = record.reader?.status || 'missing';
  stats[status] = (stats[status] || 0) + 1;
  return stats;
}, {});

const failedReaderRecords = records
  .filter((record) => record.reader?.status === 'error')
  .map((record) => ({
    rank: record.rank,
    title: record.title,
    url: record.url,
    error: record.reader?.error || null,
    retry: record.reader?.retry || null
  }));

const status = records.length > 0 && failedReaderRecords.length === records.length
  ? 'error'
  : failedReaderRecords.length > 0
    ? 'partial_error'
    : 'ok';

return {
  json: {
    status,
    provider: 'brave+jina_reader_workflow',
    query: request.query || null,
    candidateCount: request.candidateCount ?? first.candidateCount ?? records.length,
    recordCount: records.length,
    records,
    request,
    metadata: {
      braveCountRequested: request.count ?? null,
      contentFetchMode: 'all_brave_candidates',
      readerWorkflow: 'Jina Reader - Fetch URL',
      readerWorkflowHandlesRateLimit: true,
      readerStats,
      readerFailureCount: failedReaderRecords.length,
      failedReaderRecords,
      strategy: 'brave_search_all_candidates_then_jina_reader_callable_workflow',
      contentKey: 'records[].content',
      compatibilityContentKey: 'records[].reader.content',
      reranker: 'not_enabled_yet'
    },
    receivedAt: new Date().toISOString()
  }
};

let request = {};
try {
  request = $('Normalize Input').first().json;
} catch (error) {
  request = {};
}

const input = $input.item.json || {};
const error = input.error || input;
const message = typeof error === 'string'
  ? error
  : error.message || input.message || 'Web search workflow failed before producing results';

return {
  json: {
    status: 'error',
    provider: 'brave+jina_reader_workflow',
    query: request.query || input.query || null,
    candidateCount: 0,
    recordCount: 0,
    records: [],
    error: {
      message,
      name: typeof error === 'object' ? (error.name || input.name || null) : null,
      statusCode: typeof error === 'object' ? (error.statusCode || error.httpCode || input.statusCode || null) : null,
      rawPreview: JSON.stringify(input).slice(0, 2000)
    },
    request,
    receivedAt: new Date().toISOString()
  }
};
